#!/usr/bin/env python3
"""Original charts and role-separated Korean report for frozen v6."""
import csv,json,os
from pathlib import Path
os.environ.setdefault('MPLCONFIGDIR','/tmp/lineage-mpl')
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
HERE=Path(__file__).parent;ROOT=HERE.parents[1];r=json.loads((HERE/'results/report.json').read_text());assert len(r['sheets'])==19,'Incomplete evaluation';a=r['aggregate'];figures=HERE/'figures';figures.mkdir(exist_ok=True)
pct=lambda x:f'{x*100:.2f}%';pm=lambda d:' / '.join(pct(d[k]) for k in ('precision','recall','f1'))
fig,axes=plt.subplots(1,3,figsize=(15,4.8),layout='constrained');variants=['v5','v6-preview','v6'];names=['Deployed v5','Neural / 2400px','Neural / up to4800px']
for ax,metric,key,title in [(axes[0],'localization','recall','Symbol recall'),(axes[1],'connections','recall','Connection recall'),(axes[2],None,None,'Mean paired-sheet median latency')]:
 values=[a['new-page'][v][metric][key]*100 if metric else a['new-page'][v]['mean_sheet_median_seconds'] for v in variants];bars=ax.bar(np.arange(3),values,color=['#939da8','#77b7b1','#167c74']);ax.bar_label(bars,labels=[f'{x:.2f}'+('%' if metric else 's') for x in values],padding=4);ax.set_xticks(range(3),names,fontsize=9,rotation=12);ax.set_title(title);ax.spines[['top','right']].set_visible(False);ax.set_ylim(0,max(ax.get_ylim()[1]*1.15,1));ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
fig.suptitle('New pages from known projects | 32 symbols / 36 edges / 4 fixed ROIs');fig.savefig(figures/'resolution-ablation.png',dpi=170);plt.close(fig)
fig,axes=plt.subplots(1,3,figsize=(15,4.6),layout='constrained');groups=['new-page','open100-regression','pahala-p21-regression','synthetic-regression'];labels=['New-page ROIs (4)','OPEN1006–11 (6)','Pahala21 historical','Synthetic historical (8)'];x=np.arange(4)
for ax,m,k,title in [(axes[0],'localization','recall','Symbol recall'),(axes[1],'connections','f1','Connection F1'),(axes[2],None,None,'Mean median latency')]:
 for i,v in enumerate(['v5','v6']):
  values=[a[g][v][m][k]*100 if m else a[g][v]['mean_sheet_median_seconds'] for g in groups];bars=ax.bar(x+(i-.5)*.35,values,.33,color=['#939da8','#167c74'][i],label=v);ax.bar_label(bars,labels=[f'{n:.2f}'+('%' if m else 's') for n in values],fontsize=8,padding=3+9*i)
 ax.set_xticks(x,labels,fontsize=8,rotation=13);ax.set_title(title);ax.spines[['top','right']].set_visible(False);ax.set_ylim(0,max(ax.get_ylim()[1]*1.15,1));ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
axes[0].legend();axes[0].set_ylim(0,110);axes[0].set_yticks([0,20,40,60,80,100]);fig.savefig(figures/'regression-speed.png',dpi=170);plt.close(fig)
with (HERE/'per-sheet.csv').open('w',newline='') as f:
 w=csv.writer(f,lineterminator='\n');w.writerow(['group','id','role','variant','symbol_tp','symbol_fp','symbol_fn','connection_tp','connection_fp','connection_fn','connection_precision','connection_recall','connection_f1','median_seconds','min_seconds','max_seconds'])
 for s in r['sheets']:
  for v,d in s['variants'].items():w.writerow([s['group'],s['id'],s['role'],v,*[d['scores']['localization'][k] for k in ['tp','fp','fn']],*[d['scores']['connections'][k] for k in ['tp','fp','fn','precision','recall','f1']],*[d['timing'][k] for k in ['median','min','max']]])
train=json.loads((HERE/'TRAINING.json').read_text());selected=json.loads((HERE/'MODEL-SELECTION.json').read_text());new=a['new-page'];old,d=new['v5'],new['v6'];lines=['# v6 고해상도 타일·신경망 검출 개발 및 평가','',f"기준 앱 `{r['baseline']}` → 개선 앱 `844bf3b03ce34de575509bf66b531aca83ffba0d`. 평가 {r['evaluated_at']}. 실행 앱과 이후 보고서 커밋은 구분한다.",'',f"새 페이지4곳의 지정 영역에서 기호 재현율은 **{pct(old['localization']['recall'])}→{pct(d['localization']['recall'])}**, 연결 재현율은 **{pct(old['connections']['recall'])}→{pct(d['connections']['recall'])}**, 연결 F1은 **{pct(old['connections']['f1'])}→{pct(d['connections']['f1'])}**다. OCR+추출 지연은 **{old['mean_sheet_median_seconds']:.3f}→{d['mean_sheet_median_seconds']:.3f}초**다.",'','기호32개·연결36개의 작은 평가다. **새 페이지는 학습한 프로젝트에 속하며 새 프로젝트 일반화 검증이 아니다.** Virden6·8, Pāhala22, Ruttan51의 영역·정답을 새 모델 예측 전에 시각적으로 고정했다. 단일 주석자이며 독립 전문가 정답셋이나 전체 페이지 정확도로 표현하지 않는다. 원본 외관은 주석에 사용했고 정답 수정 두 건(Pāhala 출력 화살표 y 위치)은 첫 예측 전에 완료했다. [정답 고정 기록](LABELS-FROZEN.json), [주석 범위](new-page-labels.json).','','## 실제 구현과 학습','','- 기존 HOG/Random Forest 후보 분류에 더해 **YOLOX-Nano 직접 검출기**를 학습했다. COCO 사전학습 초기값에서 일반 기호1개 클래스로 머리를 교체해 전체 층을 미세조정했다. 의미·표준 식별 모델은 아니다.','- 학습 원천은 OPEN1000–3/Pāhala23·24/Virden5·7/Ruttan50·62의 실제10장·영역(4프로젝트), 이전 합성12장이다. 원천 정답1,259개에서607개 학습 타일을 만들었다. 원천 정답 수·타일 수·중복 샘플링 횟수를 독립 도면 수로 세지 않는다. v5에서 테스트했던 Virden/Ruttan 영역은 이제 학습 자료이며 이번 성능에서 보류셋으로 보고하지 않는다.','- 부분 주석 실도면은 주석된 ROI 안에서만 학습해 바깥의 미주석 기호를 음성 정답으로 쓰지 않았다. 학습 전용 좌우 반전·대비/밝기·약한 흐림을 적용했다. Pāhala/Virden/Ruttan 타일의 상대 추출 가중치는2.5이며 중복 추출한다.','',f"CPU4스레드·배치4·단계당96배치·24개 학습 단계로 총9,216개 타일 샘플을 추출해 학습했다. 전체 학습은 **{train['training_seconds_so_far']:.3f}초**였다. 8/16/24 체크포인트를 별도 검증7장으로 비교해 **16단계·점수0.6·신경망 후보 사용(neural_only)**을 선정했다. 마지막24단계는 검증 목적함수가 낮아 채택하지 않았다. [학습 기록](TRAINING.json), [선정 기록](MODEL-SELECTION.json).",'','- 타일은 최대4800px 원본에서1024px, 20%중첩으로 만들고 모델 입력640px로 변환한다. 최대36개 타일과 전체 페이지1개로 작은 기호와 큰 장비를 함께 탐색한다. 겹친 박스는 IoU0.4 억제로 합친다. 최종 기호200개·전체 요소500개 상한은 유지한다.','- 미리보기·OCR·선 추적 좌표는2400px로 유지한다. PNG/JPG는 원본을 보존해 별도 고해상도 입력을 만들고, PDF는 별도로 고해상도 렌더링한다. 타일 결과는 정규화 좌표로 합친다. DXF 원본 블록·문자 경로는 기존대로 처리한다.','- 배포는 ONNX를 기존 OpenCV DNN CPU로 실행한다. PyTorch와 학습 도구는 운영 이미지에 추가하지 않았다. 체크포인트 ONNX와 PyTorch의 흰색 시험 입력 수치 차이를 검사했고, 운영 함수가 선택 검증 결과와 일치하는지도 OPEN1004·Pāhala20에서 대조했다. 상세 차이는 모델 메타데이터에 있다.','- 선정된 neural_only 경로에서는 사용하지 않는 HOG 분류·추가 검출을 생략한다. 기존 형상 분석은 연결 추적 스타일 결정에 남아 있다. 점수는 보정된 확률이 아니며 모든 후보의 종류unknown/상태needs_review를 유지한다.','','## 해상도 비교','','동일한 선정 모델에2400px 미리보기만 입력하는 `v6-preview`도 새4페이지에서3회씩 비교했다. 이 비교는 해상도·타일 수를 바꾸며, v5→v6 비교는 데이터 확장과 검출기 교체까지 함께 바꾸므로 모델 효과만의 인과 실험으로 보지 않는다.','','| 새 페이지 지정 영역 | 기호 P / R / F1 | 연결 P / R / F1 | 지연 |','|---|---|---|---:|']
for v in variants:
 dd=new[v];lines.append(f"| {v} | {pm(dd['localization'])} | {pm(dd['connections'])} | {dd['mean_sheet_median_seconds']:.3f}초 |")
lines+=['','![해상도 대조](figures/resolution-ablation.png)','','## 회귀 결과','','| 평가 범위 | 버전 | 기호 P / R / F1 | 연결 P / R / F1 | 지연 |','|---|---|---|---|---:|']
for g in groups:
 for v in ['v5','v6']:
  dd=a[g][v];lines.append(f"| {g} | {v} | {pm(dd['localization'])} | {pm(dd['connections'])} | {dd['mean_sheet_median_seconds']:.3f}초 |")
lines+=['','![회귀·처리 시간](figures/regression-speed.png)','','OPEN1006–11·Pāhala21·합성8은 이전에 평가한 역사적 회귀다. 실제 프로젝트 PNG는 이번에 같은 원본의4800px 렌더를 양쪽 버전에 입력했다. 과거2400px 직접 렌더 PNG와 바이트가 달라 일부 기준 점수도 이전 보고서와 다르며, 이번 동일 입력의 짝 비교 수치를 따른다. 새 평가와 합쳐 새 프로젝트 성능으로 표현하지 않는다. 기호 IoU0.50 최대 일대일 매칭 및 첫 장비 무방향 인접 관계를 유지하며, 미매칭 끝점 연결도 FP로 센다. 판별된 종류 정확도나 국제표준 식별률은 주장하지 않는다.','','## 실패 사례와 남은 한계','','새 Virden6에서 기호를 더 찾았지만 정답 연결은 복구하지 못했다. Virden8은 연결을 일부 추가 복구했다. Pāhala22의 기호 재현율은 기존보다 낮아졌고, Ruttan51도 연결 TP가 없었다. 학습한 프로젝트의 새 페이지에서도 복합 밸브·펌프·작은 기호와 바운딩 박스의 범위 차이에 취약하다. 성능을 모든 도면에서 향상시켰다고 표현하지 않는다.','','기호 검출 개선이 연결로 그대로 이어지지 않았다. 포트 위치, 기호 내부를 통과하는 선, 짧은 선 단절과 교차 관례가 다음 병목이다. 이번 범위는 데이터 확장과 타일 신경망 검출까지이며, 포트·접점 신경망 및 Relationformer 공동학습을 구현·평가했다고 주장하지 않는다. 이들은 후속 비교 대상이다. 기존 X/점/T 접속 규칙을 유지하며, 온톨로지·VLM으로 보이지 않는 관계를 정답처럼 생성하지 않았다.','','## 도면별 결과','','| 집합 / ID | 버전 | 기호 TP / FP / FN | 연결 TP / FP / FN | 연결 P / R / F1 | 중앙값 초 |','|---|---|---|---|---|---:|']
for s in r['sheets']:
 for v,dd in s['variants'].items():lines.append(f"| {s['group']} / {s['id']} | {v} | {' / '.join(str(dd['scores']['localization'][k]) for k in ['tp','fp','fn'])} | {' / '.join(str(dd['scores']['connections'][k]) for k in ['tp','fp','fn'])} | {pm(dd['scores']['connections'])} | {dd['timing']['median']:.3f} |")
lines+=['','## 再現·測定 범위','','각 도면·버전3회, 반복마다 순서를 뒤집어 순차 측정했다. 총126회 추론의 모든 반복에서 박스와 연결 쌍이 동일함을 확인했다. 지연은 OCR·기호·선·연결 추론이며, 파일 전송·RGB 디코딩·축소·PDF 렌더링을 제외한다. 고해상도 처리로 계산이 늘었으며 속도가 일괄 개선됐다고 주장하지 않는다. 운영 파일 업로드 전체 시간은 별도로 [운영 검증](../../DEPLOYED_V6_VERIFICATION.ko.md)에 기록한다.','', '```bash','# Python3.12; ML dependencies isolated from runtime','.venv-ml/bin/python evaluation/v6/train.py','.venv-ml/bin/python evaluation/v6/export.py --epoch 16','# Provided immutable runtime assets recommended for exact evaluation','export PATH=/tmp/lineage-ocr-bookworm/bin:$PATH','export OMP_NUM_THREADS=1','.venv/bin/python evaluation/v6/evaluate.py','.venv/bin/python evaluation/v6/render_report.py','```','','원본은 [PID2Graph](https://zenodo.org/records/14803338), [Pāhala](https://www.epa.gov/system/files/documents/2021-08/pahala-wwtp-design-build-drawings-2021-07-23.pdf), [Virden](https://www.gov.mb.ca/sd/eal/registries/5697virden/2019-04-26_5697_00_phase_2_p_and_i_drwngs.pdf), [Ruttan](https://gov.mb.ca/sd/eal/registries/294.30/20250618_letter.pdf)이다. 실제 원본 PDF·페이지·타일·전체 OCR은 Git과 Docker 컨텍스트에서 제외한다. 도면 접근 가능성이 공개 재배포 라이선스를 뜻하지 않는다. [출처·가중치 NOTICE](../../backend/assets/NOTICE.md), [모델 카드](MODEL-CARD.ko.md), [재현 안내](REPRODUCE.ko.md), [고정 해시](FROZEN.json), [CSV](per-sheet.csv), [원시 결과](results/report.json)를 제공한다.']
(HERE/'REPORT.ko.md').write_text('\n'.join(lines).replace('再現·測定','재현·측정')+'\n');(HERE/'summary.json').write_text(json.dumps(a,indent=2)+'\n');print(json.dumps(a,indent=2))
